python3 -c "
import numpy as np
L=open('opt.xyz').read().split('\n')[2:]
A=[(l.split()[0],np.array(list(map(float,l.split()[1:4])))) for l in L if len(l.split())==4]
ti=A[0][1]
for i,(e,p) in enumerate(A):
    d=np.linalg.norm(p-ti)
    if e!='H' and d<3.0: print(i,e,round(d,2))
# bonds check
for i in range(len(A)):
  for j in range(i+1,len(A)):
    d=np.linalg.norm(A[i][1]-A[j][1])
    if {A[i][0],A[j][0]}<= {'C','Si','H'} and d<1.9 and d>0 and not (A[i][0]=='H' and A[j][0]=='H'):
      pass
import collections
cnt=collections.Counter()
for i in range(len(A)):
  n=0
  for j in range(len(A)):
    if i!=j:
      d=np.linalg.norm(A[i][1]-A[j][1]); cut={'H':1.3,'C':1.75,'Si':2.1,'Ti':2.6}
      if d< (0.5*(cut[A[i][0]]+cut[A[j][0]])): n+=1
  cnt[(A[i][0],n)]+=1
print(cnt)
"; grep -i "total energy\|converged" opt.log | tail -3
